    <script>
        function getSendTextarea() {
            const byId = document.getElementById('send_textarea') || document.getElementById('prompt_area');
            if (byId) return byId;

            const allTextareas = document.querySelectorAll('textarea');
            const visibleTextareas = [];
            for (const ta of allTextareas) {
                if (ta.hidden) continue;
                const style = window.getComputedStyle(ta);
                if (style.display === 'none' || style.visibility === 'hidden') continue;
                visibleTextareas.push(ta);
            }
            for (const ta of visibleTextareas) {
                const id = (ta.id || '').toLowerCase();
                const name = (ta.name || '').toLowerCase();
                const placeholder = (ta.placeholder || '').toLowerCase();
                const aria = (ta.getAttribute('aria-label') || '').toLowerCase();
                const dI18n = (ta.getAttribute('data-i18n') || '').toLowerCase();
                if (
                    id.includes('send') || id.includes('prompt') ||
                    name.includes('send') || name.includes('prompt') ||
                    placeholder.includes('输入') || placeholder.includes('发送') || placeholder.includes('type') || placeholder.includes('message') ||
                    aria.includes('send') || aria.includes('input') || aria.includes('message') ||
                    dI18n.includes('send') || dI18n.includes('input')
                ) return ta;
            }
            if (visibleTextareas.length === 1) return visibleTextareas[0];
            if (window.parent && window.parent !== window) {
                try {
                    const parentDoc = window.parent.document;
                    const parentById = parentDoc.getElementById('send_textarea') || parentDoc.getElementById('prompt_area');
                    if (parentById) return parentById;
                    const parentAreas = parentDoc.querySelectorAll('textarea');
                    for (const ta of parentAreas) {
                        if (ta.hidden) continue;
                        const style = parent.window.getComputedStyle(ta);
                        if (style.display === 'none' || style.visibility === 'hidden') continue;
                        const id = (ta.id || '').toLowerCase();
                        if (id.includes('send') || id.includes('prompt')) return ta;
                    }
                } catch (e) {}
            }
            return null;
        }

        function togglePanelTheme(event) {
            event.stopPropagation();
            event.preventDefault();
            const root = event.currentTarget.closest('.choices-panel-root');
            if (root) {
                root.classList.toggle('dark-mode');
                const isDark = root.classList.contains('dark-mode');
                try { localStorage.setItem('st-choices-theme-dark', isDark); } catch (e) {}
            }
        }

        (function initPanelTheme() {
            const roots = document.querySelectorAll('.choices-panel-root:not(.theme-initialized)');
            let wantsDark = false;
            try { wantsDark = localStorage.getItem('st-choices-theme-dark') === 'true'; } catch (e) {}
            roots.forEach(root => {
                if (wantsDark) root.classList.add('dark-mode');
                root.classList.add('theme-initialized');
            });
        })();

        function appendChoiceToInput(element) {
            const textElement = element.querySelector('.option-text');
            if (!textElement) return;
            const choiceText = textElement.innerText.trim();
            const textarea = getSendTextarea();

            if (textarea) {
                if (textarea.value.length > 0 && !textarea.value.match(/[\s\n]$/)) {
                    textarea.value += ' ';
                }
                textarea.value += choiceText;
                const inputEvent = new Event('input', { bubbles: true });
                textarea.dispatchEvent(inputEvent);
                textarea.focus();
            } else {
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(choiceText).catch(() => { fallbackCopy(choiceText); });
                } else {
                    fallbackCopy(choiceText);
                }
            }
        }

        function fallbackCopy(text) {
            const tmp = document.createElement('textarea');
            tmp.value = text;
            tmp.style.position = 'fixed';
            tmp.style.left = '-9999px';
            tmp.style.top = '-9999px';
            document.body.appendChild(tmp);
            tmp.focus();
            tmp.select();
            try { document.execCommand('copy'); } catch (e) {}
            document.body.removeChild(tmp);
        }
    </script>
